18:  *  $ mkdir -p build ; (cd build ; cmake -DUSE_TLS=1 .. ; make -j ; make install)
19:  *  $ clang++ --std=c++11 --stdlib=libc++ main.cpp -lixwebsocket -lz -framework Security -framework Foundation
20:  *  $ ./a.out
21:  *
22:  *  Or use cmake -DBUILD_DEMO=ON option for other platforms
23:  */
24: 
25: #include <ixwebsocket/IXNetSystem.h>
26: #include <ixwebsocket/IXWebSocket.h>
27: #include <ixwebsocket/IXUserAgent.h>
28: #include <iostream>
29: 
30: int main()
31: {
32:     // Required on Windows
33:     ix::initNetSystem();
34: 
35:     // Our websocket object
36:     ix::WebSocket webSocket;
37: 
38:     // Connect to a server with encryption
39:     // See https://machinezone.github.io/IXWebSocket/usage/#tls-support-and-configuration
40:     //     https://github.com/machinezone/IXWebSocket/issues/386#issuecomment-1105235227 (self signed certificates)
41:     std::string url("wss://echo.websocket.org");
42:     webSocket.setUrl(url);
43: 
44:     std::cout << "Connecting to " << url << "..." << std::endl;
45: 
46:     // Setup a callback to be fired (in a background thread, watch out for race conditions !)
47:     // when a message or an event (open, close, error) is received
48:     webSocket.setOnMessageCallback([](const ix::WebSocketMessagePtr& msg)
49:         {
50:             if (msg->type == ix::WebSocketMessageType::Message)
51:             {
52:                 std::cout << "received message: " << msg->str << std::endl;
53:                 std::cout << "> " << std::flush;
54:             }
55:             else if (msg->type == ix::WebSocketMessageType::Open)
56:             {
57:                 std::cout << "Connection established" << std::endl;
58:                 std::cout << "> " << std::flush;
59:             }
60:             else if (msg->type == ix::WebSocketMessageType::Error)
61:             {
62:                 // Maybe SSL is not configured properly
63:                 std::cout << "Connection error: " << msg->errorInfo.reason << std::endl;
64:                 std::cout << "> " << std::flush;
65:             }
66:         }
67:     );
68: 
69:     // Now that our callback is setup, we can start our background thread and receive messages
70:     webSocket.start();
71: 
72:     // Send a message to the server (default to TEXT mode)
73:     webSocket.send("hello world");
74: 
75:     // Display a prompt
76:     std::cout << "> " << std::flush;
77: 
78:     std::string text;
